// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type ChartAnimationProps = Record<string, any>;

// Data mimicking "Consumer Price Index for All Urban Consumers: Food at Home"
const baseData = [
  [1965, 31.5], [1966, 33.0], [1968, 35.0], [1970, 38.5],
  [1972, 41.5], [1973, 45.0], [1974, 51.5], [1975, 56.0],
  [1977, 63.0], [1979, 75.0], [1980, 82.0], [1981, 88.0],
  [1983, 95.0], [1985, 105.0], [1987, 112.0], [1990, 130.0],
  [1992, 137.0], [1995, 148.0], [1997, 155.0], [2000, 167.0],
  [2002, 176.0], [2005, 190.0], [2007, 205.0], [2008, 216.0],
  [2009, 215.0], [2010, 217.0], [2011, 226.0], [2012, 232.0],
  [2014, 240.0], [2015, 246.0], [2016, 244.0], [2018, 250.0],
  [2020, 256.0], [2021, 268.0], [2022, 298.0], [2023, 315.0],
  [2024, 320.0], [2025, 325.0]
];

// US Recession Periods mapping to the FRED chart shading
const recessions = [
  { start: 1969.9, end: 1970.8 },
  { start: 1973.8, end: 1975.2 },
  { start: 1980.0, end: 1980.5 },
  { start: 1981.5, end: 1982.8 },
  { start: 1990.5, end: 1991.2 },
  { start: 2001.2, end: 2001.8 },
  { start: 2007.9, end: 2009.5 },
  { start: 2020.1, end: 2020.3 },
];

// Linear interpolation to find the base value at any given year
function getInterpolatedValue(year: number) {
  if (year <= baseData[0][0]) return baseData[0][1];
  if (year >= baseData[baseData.length - 1][0]) return baseData[baseData.length - 1][1];
  
  for (let i = 0; i < baseData.length - 1; i++) {
    const p1 = baseData[i];
    const p2 = baseData[i + 1];
    if (year >= p1[0] && year <= p2[0]) {
      const progress = (year - p1[0]) / (p2[0] - p1[0]);
      return p1[1] + (p2[1] - p1[1]) * progress;
    }
  }
  return baseData[baseData.length - 1][1];
}

const yTicks = [0, 40, 80, 120, 160, 200, 240, 280, 320];
const xTicks = [1965, 1970, 1975, 1980, 1985, 1990, 1995, 2000, 2005, 2010, 2015, 2020, 2025];

const ChartAnimation: React.FC<ChartAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  lineColor = "#000000",
  textColor = "#000000",
  gridColor = "#000000",
  durationInSeconds = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const marginLeft = 150;
  const marginRight = 100;
  const marginTop = 160;
  const marginBottom = 160;

  const chartWidth = width - marginLeft - marginRight;
  const chartHeight = height - marginTop - marginBottom;

  const minX = 1965;
  const maxX = 2025;
  const minY = 0;
  const maxY = 320;

  const getX = (year: number) => ((year - minX) / (maxX - minX)) * chartWidth;
  const getY = (val: number) => chartHeight - ((val - minY) / (maxY - minY)) * chartHeight;

  // Generate smooth chart points
  const points = useMemo(() => {
    const pts = [];
    const steps = Math.floor(chartWidth);
    const dataMinX = baseData[0][0];
    const dataMaxX = baseData[baseData.length - 1][0];

    for (let i = 0; i <= steps; i++) {
      const year = minX + (maxX - minX) * (i / steps);
      if (year >= dataMinX && year <= dataMaxX) {
        const val = getInterpolatedValue(year);
        pts.push({ x: getX(year), y: getY(val) });
      }
    }
    return pts;
  }, [chartWidth, chartHeight]);

  const pathData = useMemo(() => {
    return points.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`).join(" ");
  }, [points]);

  // Animation timing
  const durationInFrames = durationInSeconds * fps;
  const drawStart = 20;
  const drawEnd = durationInFrames - 30;

  // Global opacity for base axes elements
  const contentOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Wiping clip path to reveal the chart over time
  const drawProgress = interpolate(frame, [drawStart, drawEnd], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate the active leading dot based on the wiped path distance
  const currentChartX = chartWidth * drawProgress;
  const revealedPoints = points.filter(p => p.x <= currentChartX);
  const leadingPoint = revealedPoints.length > 0 ? revealedPoints[revealedPoints.length - 1] : null;

  const dotOpacity = interpolate(
    drawProgress,
    [0, 0.02, 0.98, 1],
    [0, 1, 1, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, transition: "none" }}>
      <svg width={width} height={height} style={{ transition: "none", opacity: contentOpacity }}>
        
        {/* Main Titles (FRED Style) */}
        <g transform={`translate(${marginLeft}, 80)`}>
          <text
            x={0}
            y={0}
            textAnchor="start"
            fontSize={64}
            fontWeight={900}
            fill={textColor}
            style={{ transition: "none", letterSpacing: "-0.04em" }}
          >
            FRED®
          </text>
          
          <text
            x={210}
            y={-5}
            textAnchor="start"
            fontSize={32}
            fontWeight={300}
            fill={textColor}
            style={{ transition: "none" }}
          >
            — Consumer Price Index for All Urban Consumers: Food at Home in U.S. City Average
          </text>
        </g>

        {/* Y-Axis Label */}
        <text
          x={-(marginTop + chartHeight / 2)}
          y={marginLeft - 70}
          transform="rotate(-90)"
          textAnchor="middle"
          fontSize={24}
          fontWeight={400}
          fill={textColor}
          style={{ transition: "none" }}
        >
          Index 1982-1984=100
        </text>

        <g transform={`translate(${marginLeft}, ${marginTop})`}>
          
          {/* Chart Bounding Box */}
          <rect
            x={0}
            y={0}
            width={chartWidth}
            height={chartHeight}
            fill="none"
            stroke={textColor}
            strokeWidth={1.5}
            style={{ transition: "none" }}
          />

          {/* Recession Shading */}
          {recessions.map((r, i) => {
            const startX = getX(r.start);
            const endX = getX(r.end);
            if (endX < 0 || startX > chartWidth) return null;
            const rectX = Math.max(0, startX);
            const rectW = Math.min(chartWidth - rectX, endX - rectX);

            return (
              <rect
                key={`rec-${i}`}
                x={rectX}
                y={0}
                width={rectW}
                height={chartHeight}
                fill={textColor}
                opacity={0.06}
                style={{ transition: "none" }}
              />
            );
          })}

          {/* X-axis Ticks & Gridlines */}
          {xTicks.map((tick) => (
            <g key={`x-${tick}`} transform={`translate(${getX(tick)}, 0)`} style={{ transition: "none" }}>
              {/* Vertical Solid Grid Line */}
              <line x1={0} y1={0} x2={0} y2={chartHeight} stroke={gridColor} strokeWidth={1} opacity={0.3} />
              {/* Ticks crossing top and bottom borders */}
              <line x1={0} y1={-6} x2={0} y2={6} stroke={textColor} strokeWidth={1} />
              <line x1={0} y1={chartHeight - 6} x2={0} y2={chartHeight + 6} stroke={textColor} strokeWidth={1} />
              {/* Tick Label */}
              <text x={0} y={chartHeight + 35} textAnchor="middle" fontSize={20} fill={textColor}>
                {tick}
              </text>
            </g>
          ))}

          {/* Y-axis Ticks & Gridlines */}
          {yTicks.map((tick) => (
            <g key={`y-${tick}`} transform={`translate(0, ${getY(tick)})`} style={{ transition: "none" }}>
              {/* Horizontal Solid Grid Line */}
              <line x1={0} y1={0} x2={chartWidth} y2={0} stroke={gridColor} strokeWidth={1} opacity={0.3} />
              {/* Ticks crossing left and right borders */}
              <line x1={-6} y1={0} x2={6} y2={0} stroke={textColor} strokeWidth={1} />
              <line x1={chartWidth - 6} y1={0} x2={chartWidth + 6} y2={0} stroke={textColor} strokeWidth={1} />
              {/* Tick Label */}
              <text x={-15} y={6} textAnchor="end" fontSize={20} fill={textColor}>
                {tick}
              </text>
            </g>
          ))}

          {/* --- Animated Reveal Section --- */}
          <clipPath id="reveal-clip">
            <rect
              x={-20}
              y={-50}
              width={(chartWidth + 40) * drawProgress}
              height={chartHeight + 100}
            />
          </clipPath>

          <g clipPath="url(#reveal-clip)" style={{ transition: "none" }}>
            {/* Main Data Line */}
            <path
              d={pathData}
              fill="none"
              stroke={lineColor}
              strokeWidth={3}
              strokeLinejoin="round"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          </g>

          {/* Leading edge dot moving exactly with the clip path */}
          {leadingPoint && (
            <circle
              cx={leadingPoint.x}
              cy={leadingPoint.y}
              r={6}
              fill={lineColor}
              opacity={dotOpacity}
              style={{ transition: "none" }}
            />
          )}
        </g>

        {/* Source References at Bottom */}
        <text
          x={marginLeft}
          y={height - 70}
          textAnchor="start"
          fontSize={18}
          fontWeight={400}
          fill={textColor}
          opacity={0.8}
          style={{ transition: "none" }}
        >
          Source: U.S. Bureau of Labor Statistics via FRED®
        </text>
        <text
          x={marginLeft}
          y={height - 45}
          textAnchor="start"
          fontSize={18}
          fontWeight={400}
          fill={textColor}
          opacity={0.8}
          style={{ transition: "none" }}
        >
          Shaded areas indicate U.S. recessions.
        </text>

        <text
          x={width - marginRight}
          y={height - 50}
          textAnchor="end"
          fontSize={18}
          fontWeight={400}
          fill={textColor}
          opacity={0.8}
          style={{ transition: "none" }}
        >
          fred.stlouisfed.org
        </text>

      </svg>
    </AbsoluteFill>
  );
};

export default ChartAnimation;